// A subset of the bundled Inter variable face, used inside the printed SVG.

// An SVG loaded through <img> cannot use the document webfont; embedding the
// subset lets the diagram keep the app's label face instead of falling back to
// the system sans. Generated with:
//   pyftsubset ui/fonts/InterVariable.woff2 \
//     --unicodes="U+0020-007E,U+00B0" --flavor=woff2 --layout-features='*'
// The Inter OFL in licenses/ covers the original; this is a derived subset.

export const DIAGRAM_FONT = "data:font/woff2;base64,";
